--
-- Name: generate_shipment_codes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_shipment_codes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    seq_number BIGINT;
BEGIN
    IF NEW.nomor_resi IS NULL OR NEW.nomor_resi = '' THEN
        seq_number := nextval('public.shipment_receipt_seq'::regclass);

        NEW.nomor_resi :=
            'SST-' ||
            to_char(CURRENT_DATE, 'YYYYMMDD') ||
            '-' ||
            lpad(seq_number::TEXT, 8, '0');
    END IF;

    IF NEW.barcode_value IS NULL OR NEW.barcode_value = '' THEN
        NEW.barcode_value := NEW.nomor_resi;
    END IF;

    RETURN NEW;
END;
$$;


