    pengirim_kota character varying(100),
    pengirim_kode_pos character varying(10),
    pengirim_latitude numeric(10,8),
    pengirim_longitude numeric(11,8),
    penerima_nama character varying(100) NOT NULL,
    penerima_no_hp character varying(20) NOT NULL,
    penerima_alamat text NOT NULL,
    penerima_kota character varying(100),
    penerima_kode_pos character varying(10),
    penerima_latitude numeric(10,8),
    penerima_longitude numeric(11,8),
    total_berat_gram integer DEFAULT 0 NOT NULL,
    panjang_cm numeric(10,2),
    lebar_cm numeric(10,2),
    tinggi_cm numeric(10,2),
    total_barang integer DEFAULT 1 NOT NULL,
    nilai_barang numeric(14,2) DEFAULT 0 NOT NULL,
    biaya_pengiriman numeric(14,2) DEFAULT 0 NOT NULL,
    biaya_asuransi numeric(14,2) DEFAULT 0 NOT NULL,
    biaya_layanan_tambahan numeric(14,2) DEFAULT 0 NOT NULL,
    diskon numeric(14,2) DEFAULT 0 NOT NULL,
    total_biaya numeric(14,2) DEFAULT 0 NOT NULL,
    metode_pembayaran character varying(20) DEFAULT 'TRANSFER'::character varying NOT NULL,
    catatan_pengiriman text,
    estimasi_tiba date,
    picked_up_at timestamp with time zone,
    delivered_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT t_shipments_biaya_asuransi_check CHECK ((biaya_asuransi >= (0)::numeric)),
    CONSTRAINT t_shipments_biaya_layanan_tambahan_check CHECK ((biaya_layanan_tambahan >= (0)::numeric)),
    CONSTRAINT t_shipments_biaya_pengiriman_check CHECK ((biaya_pengiriman >= (0)::numeric)),
    CONSTRAINT t_shipments_diskon_check CHECK ((diskon >= (0)::numeric)),
    CONSTRAINT t_shipments_metode_pembayaran_check CHECK (((metode_pembayaran)::text = ANY ((ARRAY['TRANSFER'::character varying, 'COD'::character varying, 'CASH'::character varying, 'E_WALLET'::character varying])::text[]))),
    CONSTRAINT t_shipments_nilai_barang_check CHECK ((nilai_barang >= (0)::numeric)),
    CONSTRAINT t_shipments_penerima_latitude_check CHECK (((penerima_latitude IS NULL) OR ((penerima_latitude >= ('-90'::integer)::numeric) AND (penerima_latitude <= (90)::numeric)))),
    CONSTRAINT t_shipments_penerima_longitude_check CHECK (((penerima_longitude IS NULL) OR ((penerima_longitude >= ('-180'::integer)::numeric) AND (penerima_longitude <= (180)::numeric)))),
    CONSTRAINT t_shipments_pengirim_latitude_check CHECK (((pengirim_latitude IS NULL) OR ((pengirim_latitude >= ('-90'::integer)::numeric) AND (pengirim_latitude <= (90)::numeric)))),
    CONSTRAINT t_shipments_pengirim_longitude_check CHECK (((pengirim_longitude IS NULL) OR ((pengirim_longitude >= ('-180'::integer)::numeric) AND (pengirim_longitude <= (180)::numeric)))),
    CONSTRAINT t_shipments_total_barang_check CHECK ((total_barang > 0)),
    CONSTRAINT t_shipments_total_berat_gram_check CHECK ((total_berat_gram >= 0)),
    CONSTRAINT t_shipments_total_biaya_check CHECK ((total_biaya >= (0)::numeric))
);


